-- 0100: preserve 38 DHET 2026 occupational-qualification row claims as private review work.
-- No route_programmes, route providers, deadlines, eligibility rules or public opportunity records
-- are created by this migration. The current PDF extraction could not be visually confirmed;
-- each row and raw college-name list must be checked before creating provider-programme links.
BEGIN;

INSERT INTO public.source_authorities (
  source_key, source_name, source_type, base_url, default_confidence_band,
  verification_required, last_verified_at, verification_notes
) VALUES (
  'dhet_tvet_occupational_programmes_2026',
  'DHET 2026 Occupational Qualifications Offered at Public TVET Colleges',
  'government_institution_list',
  'https://www.dhet.gov.za/Technical%20and%20Vocational%20Education%20and%20Training%20Co/List%20of%20Occupational%20Programmes%20updated%20for%202026%20for%20website.pdf',
  'C',
  true,
  NULL,
  'Official DHET 2026 PDF source anchor. It records names and source text only; extracted programme/provider pairings require row-by-row human visual review. No open intake, deadline, eligibility, provider route, partner status or submission capability is implied.'
)
ON CONFLICT (source_key) DO NOTHING;

DO $preflight$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.source_authorities
    WHERE source_key = 'dhet_tvet_occupational_programmes_2026'
      AND base_url = 'https://www.dhet.gov.za/Technical%20and%20Vocational%20Education%20and%20Training%20Co/List%20of%20Occupational%20Programmes%20updated%20for%202026%20for%20website.pdf'
      AND verification_required = true
  ) THEN
    RAISE EXCEPTION 'DHET_2026_TVET_OCCUPATIONAL_SOURCE_ANCHOR_MISSING_OR_CONFLICTING';
  END IF;
END
$preflight$;

INSERT INTO public.opportunity_source_authorities (
  authority_ref, authority_name, authority_type, base_url, sector_scope,
  confidence_band, active, notes
) VALUES (
  'dhet_tvet_occupational_programmes_2026',
  'DHET 2026 Occupational Qualifications Offered at Public TVET Colleges',
  'government_institution_list',
  'https://www.dhet.gov.za/Technical%20and%20Vocational%20Education%20and%20Training%20Co/List%20of%20Occupational%20Programmes%20updated%20for%202026%20for%20website.pdf',
  ARRAY['TVET','SETA','LEARNERSHIP','APPRENTICESHIP']::text[],
  'MEDIUM',
  true,
  'Official source anchor only. Qualification/provider rows have been transcribed from extracted PDF text and remain NEEDS_REVIEW until an independent human checks the rendered source layout. Source authority status is not programme, intake, deadline, eligibility or delivery proof.'
)
ON CONFLICT (authority_ref) DO NOTHING;

DO $bridge_preflight$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.opportunity_source_authorities
    WHERE authority_ref = 'dhet_tvet_occupational_programmes_2026'
      AND base_url = 'https://www.dhet.gov.za/Technical%20and%20Vocational%20Education%20and%20Training%20Co/List%20of%20Occupational%20Programmes%20updated%20for%202026%20for%20website.pdf'
      AND sector_scope @> ARRAY['TVET']::text[]
  ) THEN
    RAISE EXCEPTION 'DHET_2026_TVET_OCCUPATIONAL_BRIDGE_MISSING_OR_CONFLICTING';
  END IF;
END
$bridge_preflight$;

