ON CONFLICT (observation_ref) DO NOTHING;

DO $verify$
DECLARE
  v_total integer;
  v_review_only integer;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE observation_status IN ('DRAFT','NEEDS_REVIEW'))
    INTO v_total, v_review_only
  FROM public.external_source_observations
  WHERE observation_ref LIKE 'dhet_2026_tvet_occ_%';

  IF v_total <> 38 THEN
    RAISE EXCEPTION 'Expected 38 DHET occupational source observations; found %', v_total;
  END IF;
  IF v_review_only < 38 THEN
    RAISE EXCEPTION 'Expected all 38 new DHET observations to remain review-only; review status mismatch found';
  END IF;
END
$verify$;

COMMIT;
